  add('date','日期选择','Date Picker','表单',false,'选择具体日期；原生输入支持手动输入，日历作为可见辅助。','当前日、选中日、跨月、跨年、闰年、输入同步。','日历方向键、Home / End、PageUp / PageDown；每个日期有完整可读名称。','component.input-height · radius.card · semantic.action',()=>`<div class="stack"><div class="field"><label for="calendar-input">计划开始日期</label><input type="date" id="calendar-input"></div><div class="calendar" data-calendar data-input="calendar-input" data-output="calendar-output"></div><output id="calendar-output" class="hint" for="calendar-input"></output></div>`,`<input type="date" id="start-date">\n<div class="calendar" data-calendar data-input="start-date"></div>`);
  add('select','下拉选择','Select','表单',false,'统一外观的选择控件；展开面板、分组选项、当前选中和禁用状态都可直接查看。','占位、展开、选中、focus、disabled、error。','自制下拉面板与 listbox；方向键 / Home / End 导航，Enter 确认，Esc 取消；原生 select 保留为表单数据源。','component.input-height · radius.control · semantic.control-border',()=>`<div class="stack"><div class="field"><label for="select-demo">学习方向</label><select id="select-demo"><option value="">请选择方向</option><optgroup label="内容与方法"><option>调研与观察</option><option>设计与表达</option></optgroup><optgroup label="实践"><option>手艺与制作</option></optgroup></select><output id="select-result" class="hint">尚未选择</output></div><div class="field"><label for="select-disabled">后续专题</label><select id="select-disabled" disabled><option>尚未开放</option></select></div></div>`,`<label for="topic">方向</label><select id="topic"><option>调研</option></select>`);
  add('upload','文件选择与上传边界','Upload','表单',false,'选择附件、校验格式和大小、查看与移除已选文件；真实上传需接入服务端。','空白、拖拽、已选、格式错误、超过大小限制、移除。','原生 file input；错误关联 aria-describedby；拖拽可用选择按钮替代。','semantic.control-border · radius.card · color.surface-blue',()=>`<div data-upload><div class="dropzone" role="group" aria-labelledby="upload-title">${I('upload')}<strong style="display:block" id="upload-title">选择或拖入参考资料</strong><span class="hint">PDF / JPG / PNG，单个不超过 5 MB，最多 3 个。</span><div class="row" style="justify-content:center;margin-top:16px"><button class="btn primary" type="button" data-file-trigger="file-demo" aria-describedby="file-error file-note">${I('upload')}选择文件</button></div><input id="file-demo" type="file" multiple accept=".pdf,.jpg,.jpeg,.png" aria-label="选择参考资料文件" aria-describedby="file-error file-note" hidden></div><p class="error-text mt" id="file-error" role="alert" data-file-error></p><div data-files></div><p class="hint mt" id="file-note">仅本地选择和校验，不向服务器上传。</p></div>`,`<input type="file" accept=".pdf,.jpg,.png" multiple>\n// DS.validateFiles([...input.files])`);
  add('form','表单组合与验证','Form','表单',true,'把标签、输入、辅助信息、错误与提交动作组合成可完成的任务。','初始、编辑、字段错误、校验通过、本地保存；错误聚焦首个问题。','required 与 aria-invalid；错误关联字段；提交结果 role=status；不抢先逐字报错。','space.4 · semantic.danger · semantic.action',formDemo,`<form data-demo-form novalidate>\n  <label for="goal">学习目标</label>\n  <input id="goal" name="title" required>\n  <button type="submit">保存</button>\n</form>`);
  add('richtext','教程正文','Rich Text','内容',true,'统一长文的标题、段落、列表、引言、图注和链接，维持连续阅读。','h1-h3 层级、列表、引用、图注；长内容自然换行。','语义标题有序；不跳级；正文至少 16 px；图片附 alt 和来源。','component.reading-width · font-size.body · space.6',()=>`<article class="rich"><h3 style="margin-top:0">先问这次要决定什么</h3><p>同样看一张图，有人关注颜色，有人关注动作。目标不同，应该留下的记录也不同。</p><blockquote>把想法写清楚，再让证据来回答。</blockquote><ul><li>我准备支持哪个决定？</li><li>需要观察哪些具体对象？</li><li>怎样知道这次取样已经够用？</li></ul></article>`,`<article class="rich"><h2>明确目标</h2><p>说明与例子。</p><blockquote>一句引言</blockquote></article>`);
  add('code','代码块','Code Block','内容',true,'展示可复制的实现片段；长行在代码容器内滚动，不撑破正文。','语言标签、代码、复制成功/受限回退。','pre/code 保留格式；复制按钮明确；失败时选中代码供手动复制。','font.mono · color.ink · radius.card',()=>code('code-demo-source',':root {\n  --semantic-action: #20A0E0;\n  --radius-control: 10px;\n}\n\n.btn.primary {\n  background: var(--semantic-action);\n  color: white;\n}'),`<pre><code>const value = 1;</code></pre>`);
